function hasPendingPour() {
  return Boolean(pourSequence?.state.pendingStepId);
}

function setStatus(text, sub) {
  if (statusText) statusText.textContent = text;
  if (statusSub) statusSub.textContent = sub;
}

function updateHalideWidget() {
  const steps = [
    { el: halideTube1, key: "add-agno3-to-naf", row: halideRows.tube1 },
    { el: halideTube2, key: "add-agno3-to-nacl", row: halideRows.tube2 },
    { el: halideTube3, key: "add-agno3-to-nabr", row: halideRows.tube3 },
    { el: halideTube4, key: "add-agno3-to-nai", row: halideRows.tube4 },
  ];
  for (const { el, key, row } of steps) {
    const config = stepMap[key];
    if (el) {
      el.textContent = state.completedSteps[key]
        ? config.widgetText
        : state.activePour?.stepId === key
          ? 'Đang phản ứng...'
          : 'Chưa thao tác.';
    }
    if (row) {
      row.dataset.state = state.completedSteps[key]
        ? config.widgetState
        : state.activePour?.stepId === key ? 'reacting' : 'idle';
    }
  }
  if (halideConclusion) {
    halideConclusion.textContent = allManualStepsDone()
      ? 'NaF: không kết tủa. NaCl: trắng. NaBr: vàng nhạt. NaI: vàng. Nhận biết ion halide qua màu AgX.'
      : 'Kết luận sẽ hiện sau khi hoàn tất cả bốn ống nghiệm.';
  }
}

function setTubeProgress(keys, progress) {
  for (const key of keys) {
    tubeTransitions[key].setProgress(progress);
  }
}

function allManualStepsDone() {
  return state.completedSteps["add-agno3-to-naf"]
    && state.completedSteps["add-agno3-to-nacl"]
    && state.completedSteps["add-agno3-to-nabr"]
    && state.completedSteps["add-agno3-to-nai"];
}

function isMotionActive() {
  return agno3Motion.state.active;
}

function renderStatus() {
  updateHalideWidget();

  if (state.phase === 'result') {
    setStatus(
      'Kết quả: nhận biết ion halide bằng AgNO₃ thành công.',
      'NaF: không kết tủa. NaCl: AgCl trắng. NaBr: AgBr vàng nhạt. NaI: AgI vàng.'
    );
    return;
  }

  if (state.activePour) {
    const percent = Math.round(state.activePour.progress * 100);
    setStatus(state.activePour.title, state.activePour.sub + ' Tiến trình: ' + percent + '%.');
    return;
  }

  if (hasPendingPour() || isMotionActive()) {
    setStatus('Đang đưa chai AgNO₃ vào vị trí nhỏ.', 'Chai được di chuyển và nghiêng ngay trên miệng ống nghiệm trước khi phản ứng.');
    return;
  }

  if (allManualStepsDone()) {
    setStatus('Cả bốn ống nghiệm đã hoàn tất.', 'Có thể kết luận: AgNO₃ nhận biết halide qua màu kết tủa AgX.');
    return;
  }

  const doneCount = ["add-agno3-to-naf", "add-agno3-to-nacl", "add-agno3-to-nabr", "add-agno3-to-nai"]
    .filter((id) => state.completedSteps[id]).length;
  if (doneCount > 0) {
    setStatus('Đã xong ' + doneCount + '/4 ống nghiệm.', 'Tiếp tục nhỏ AgNO₃ vào ống kế tiếp.');
    return;
  }

  setStatus(
    'Sẵn sàng. Hãy nhỏ AgNO₃ vào từng ống NaF, NaCl, NaBr, NaI.',
    "Bài \"So sánh màu kết tủa AgX để nhận biết ion halide\" dùng classic-kit: camera gần, ống nghiệm lớn, chỉ đổi màu trong phạm vi chất lỏng.",
  );
}

function startPourEffect(config, mode) {
  state.phase = mode === 'autoplay' ? 'autoplay' : 'reaction';
  state.activeStep = config.stepId;
  state.reactionProgress = 0;
  state.activePour = {
    stepId: config.stepId,
    bottleId: config.bottleId,
    bottle: config.bottle,
    tube: config.tube,
    title: config.title,
    sub: config.sub,
    progress: 0,
    transitions: config.transitions,
    streamColor: config.streamColor,
    mode,
  };
  pourStream.mesh.material.color.set(config.streamColor);
  pourStream.mesh.material.emissive.set(config.streamColor);
  renderStatus();
}

function finalizePourEffect(config) {
  if (!state.activePour) {
    return false;
  }
  setTubeProgress(config.transitions, 1);
  state.completedSteps[config.stepId] = true;
  state.activePour = null;
  state.phase = 'idle';
  state.reactionProgress = 0;
  pourStream.reset();
  dragController.setEnabled(true);
  renderStatus();
  return true;
}

function beginPour(stepId, mode = 'manual') {
  const config = stepMap[stepId];
  if (!config || state.completedSteps[stepId] || state.activePour || hasPendingPour() || isMotionActive()) {
    return false;
  }
  if (mode === 'autoplay') {
    return pourSequence.beginStep(stepId, mode);
  }
  return pourSequence.beginStepFromActiveDrag(stepId);
}

function finishReaction() {
  agno3Motion.cancel({ restoreDrag: true });
  pourSequence.reset();
  if (state.activePour) {
    finalizePourEffect(stepMap[state.activePour.stepId] || state.activePour);
  }
  for (const stepId of ["add-agno3-to-naf", "add-agno3-to-nacl", "add-agno3-to-nabr", "add-agno3-to-nai"]) {
    if (!state.completedSteps[stepId]) {
      setTubeProgress(stepMap[stepId].transitions, 1);
      state.completedSteps[stepId] = true;
    }
  }
  state.autoplayDelay = 0;
  state.phase = 'result';
  state.activeStep = "finish-reaction";
  state.reactionProgress = 1;
  pourStream.reset();
  dragController.setEnabled(true);
  renderStatus();
  return true;
}

function resetScene() {
  agno3Motion.cancel({ restoreDrag: true });
  dragController.setEnabled(true);
  dragController.reset();
  state.phase = 'idle';
  state.activeStep = 'ready';
  state.reactionProgress = 0;
  state.activePour = null;
  state.autoplayDelay = 0;
  pourSequence.reset();
  state.completedSteps["add-agno3-to-naf"] = false;
  state.completedSteps["add-agno3-to-nacl"] = false;
  state.completedSteps["add-agno3-to-nabr"] = false;
  state.completedSteps["add-agno3-to-nai"] = false;
  pourStream.reset();
  tubeTransitions.tube1Liquid.reset();
  tubeTransitions.tube1Surface.reset();
  tubeTransitions.tube2Liquid.reset();
  tubeTransitions.tube2Surface.reset();
  tubeTransitions.tube3Liquid.reset();
  tubeTransitions.tube3Surface.reset();
  tubeTransitions.tube4Liquid.reset();
  tubeTransitions.tube4Surface.reset();
  renderStatus();
}

